// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(this));
        vm.assume(caller != address(c));
        uint256 balanceBefore = caller.balance;
        uint256 amountToSend = bound(amount, 0, balanceBefore);
        bool reverted;
        try c.sendTo(caller, amountToSend) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balanceAfter = caller.balance;
        // The rule: when caller is not the owner, the call should revert (or if it succeeded, caller's balance must still be unchanged because the owner is the only one who can send).
        // Here we assume 'owner' is set at construction to address(this), so any other caller is not owner.
        // If the call succeeded mistakenly, the caller's balance would be decreased by amountToSend (due to transfer).
        // We assert that caller's balance did not change, which holds iff the call reverted (correct behavior) or reverted because the reference reverts on non-owner.
        assertTrue(balanceAfter == balanceBefore);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public { 
        c = new C(); 
        owner = address(this);
    }

    function testFuzz_property(address receiver, uint256 amount) public {
        // Bound amount to avoid overflows and ensure enough balance
        amount = bound(amount, 0, address(this).balance);

        // Record balances before
        uint256 ownerBalanceBefore = address(this).balance;
        uint256 receiverBalanceBefore = receiver.balance;

        // Call sendTo — works for owner, could fail for others in reference
        c.sendTo(receiver, amount);

        // After call: owner balance + receiver balance should be unchanged
        uint256 ownerBalanceAfter = address(this).balance;
        uint256 receiverBalanceAfter = receiver.balance;

        assertTrue(
            ownerBalanceBefore + receiverBalanceBefore == 
            ownerBalanceAfter + receiverBalanceAfter,
            "Sum of owner+receiver balances changed"
        );
    }
}

