    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(amount > 0 && amount <= address(c).balance);
        vm.deal(caller, 100 ether);
        uint256 callerBalanceBefore = address(caller).balance;
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.sendTo.selector, address(0x123), amount));
        uint256 callerBalanceAfter = address(caller).balance;
        assertTrue(callerBalanceBefore == callerBalanceAfter);
    }
}
